import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class Solution {
    enum Politica { DESCARTAR_NOVO, DESCARTAR_ANTIGO, ERRO, BLOQUEAR }

    record Publicacao<T>(boolean aceito, T descartado) {}

    static class FilaLimitada<T> {
        private final int capacidade;
        private final Politica politica;
        private final Deque<T> itens = new ArrayDeque<>();
        private final Lock lock = new ReentrantLock();
        private final Condition naoVazia = lock.newCondition();
        private final Condition naoCheia = lock.newCondition();
        private long publicados;
        private long descartados;

        FilaLimitada(int capacidade, Politica politica) {
            if (capacidade <= 0) {
                throw new IllegalArgumentException("capacidade deve ser positiva");
            }
            if (politica == null) {
                throw new IllegalArgumentException("politica obrigatoria");
            }
            this.capacidade = capacidade;
            this.politica = politica;
        }

        Publicacao<T> publicar(T item) throws InterruptedException {
            if (item == null) {
                throw new IllegalArgumentException("item obrigatorio");
            }
            lock.lockInterruptibly();
            try {
                if (itens.size() == capacidade) {
                    switch (politica) {
                        case DESCARTAR_NOVO -> {
                            descartados++;
                            return new Publicacao<>(false, item);
                        }
                        case DESCARTAR_ANTIGO -> {
                            T antigo = itens.removeFirst();
                            itens.addLast(item);
                            descartados++;
                            publicados++;
                            naoVazia.signal();
                            return new Publicacao<>(true, antigo);
                        }
                        case ERRO -> throw new IllegalStateException("fila cheia");
                        case BLOQUEAR -> {
                            while (itens.size() == capacidade) {
                                naoCheia.await();
                            }
                        }
                    }
                }
                itens.addLast(item);
                publicados++;
                naoVazia.signal();
                return new Publicacao<>(true, null);
            } finally {
                lock.unlock();
            }
        }

        T consumir() {
            lock.lock();
            try {
                T item = itens.pollFirst();
                if (item != null) {
                    naoCheia.signal();
                }
                return item;
            } finally {
                lock.unlock();
            }
        }

        List<T> consumir(int max) {
            if (max < 0) {
                throw new IllegalArgumentException("max nao pode ser negativo");
            }
            var resultado = new ArrayList<T>(Math.min(max, tamanho()));
            for (int i = 0; i < max; i++) {
                T item = consumir();
                if (item == null) {
                    break;
                }
                resultado.add(item);
            }
            return List.copyOf(resultado);
        }

        int tamanho() {
            lock.lock();
            try {
                return itens.size();
            } finally {
                lock.unlock();
            }
        }

        long publicados() {
            lock.lock();
            try {
                return publicados;
            } finally {
                lock.unlock();
            }
        }

        long descartados() {
            lock.lock();
            try {
                return descartados;
            } finally {
                lock.unlock();
            }
        }
    }
}

