import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;

class SolutionTest {
    @Test void descartaNovoQuandoCheia() throws Exception {
        var fila = new Solution.FilaLimitada<String>(2, Solution.Politica.DESCARTAR_NOVO);

        assertTrue(fila.publicar("a").aceito());
        assertTrue(fila.publicar("b").aceito());
        var terceiro = fila.publicar("c");

        assertFalse(terceiro.aceito());
        assertEquals("c", terceiro.descartado());
        assertEquals(2, fila.tamanho());
        assertEquals(2, fila.publicados());
        assertEquals(1, fila.descartados());
        assertEquals(List.of("a", "b"), fila.consumir(10));
    }

    @Test void descartaAntigoQuandoCheia() throws Exception {
        var fila = new Solution.FilaLimitada<String>(2, Solution.Politica.DESCARTAR_ANTIGO);
        fila.publicar("a");
        fila.publicar("b");

        var terceiro = fila.publicar("c");

        assertTrue(terceiro.aceito());
        assertEquals("a", terceiro.descartado());
        assertEquals(3, fila.publicados());
        assertEquals(1, fila.descartados());
        assertEquals(List.of("b", "c"), fila.consumir(10));
    }

    @Test void erroNaoAlteraEstado() throws Exception {
        var fila = new Solution.FilaLimitada<String>(1, Solution.Politica.ERRO);
        fila.publicar("a");

        assertThrows(IllegalStateException.class, () -> fila.publicar("b"));
        assertEquals(1, fila.tamanho());
        assertEquals(1, fila.publicados());
        assertEquals(0, fila.descartados());
        assertEquals("a", fila.consumir());
    }

    @Test void bloqueiaAteHaverEspaco() throws Exception {
        var fila = new Solution.FilaLimitada<String>(2, Solution.Politica.BLOQUEAR);
        fila.publicar("a");
        fila.publicar("b");

        var publicou = new AtomicBoolean();
        var produtor = new Thread(() -> {
            try {
                fila.publicar("c");
                publicou.set(true);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });
        produtor.start();
        Thread.sleep(100);

        assertFalse(publicou.get());
        assertEquals(2, fila.tamanho());

        assertEquals("a", fila.consumir());
        produtor.join(1000);

        assertFalse(produtor.isAlive());
        assertTrue(publicou.get());
        assertEquals(3, fila.publicados());
        assertEquals(List.of("b", "c"), fila.consumir(10));
    }

    @Test void consumirRespeitaMaximo() throws Exception {
        var fila = new Solution.FilaLimitada<Integer>(5, Solution.Politica.ERRO);
        fila.publicar(1);
        fila.publicar(2);
        fila.publicar(3);

        assertEquals(List.of(1, 2), fila.consumir(2));
        assertEquals(1, fila.tamanho());
        assertEquals(List.of(), fila.consumir(0));
        assertEquals(List.of(3), fila.consumir(10));
        assertNull(fila.consumir());
        assertThrows(IllegalArgumentException.class, () -> fila.consumir(-1));
    }

    @Test void validaArgumentos() {
        assertThrows(IllegalArgumentException.class,
                () -> new Solution.FilaLimitada<String>(0, Solution.Politica.ERRO));
        assertThrows(IllegalArgumentException.class,
                () -> new Solution.FilaLimitada<String>(1, null));

        var fila = new Solution.FilaLimitada<String>(1, Solution.Politica.ERRO);
        assertThrows(IllegalArgumentException.class, () -> fila.publicar(null));
    }
}
